<body>
<div class="wrap">
  <header class="masthead">
    <span class="mark" aria-hidden="true">
      <svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 4v16"/><path d="M11 9h6M11 13h6M11 17h4"/></svg>
    </span>
    <div>
      <h1>Napló</h1>
      <p class="tagline">Napra szóló jegyzetek — írd le a mai napot, és mentsd el.</p>
    </div>
  </header>

  <section class="composer">
    <label for="newEntry">Új bejegyzés</label>
    <textarea id="newEntry" placeholder="Mit szeretnél feljegyezni?"></textarea>
    <div class="composer-foot">
      <span class="hint">Enter: új sor · Ctrl + Enter: mentés</span>
      <button id="addBtn" class="btn btn-primary" type="button">Hozzáad</button>
    </div>
  </section>

  <div class="toolbar">
    <input id="search" class="search" type="search" placeholder="Keresés a bejegyzésekben…" aria-label="Keresés a bejegyzésekben">
    <span id="count" class="count" aria-live="polite"></span>
  </div>

  <div id="list"></div>
  <div id="status" class="sr-only" aria-live="polite"></div>
</div>

<script>
(function(){
  var KEY = 'naplo.entries.v1';
  var entries = [];
  var query = '';
  var editingId = null;
  var confirmId = null;

  var list = document.getElementById('list');
  var input = document.getElementById('newEntry');
  var addBtn = document.getElementById('addBtn');
  var search = document.getElementById('search');
  var countEl = document.getElementById('count');
  var statusEl = document.getElementById('status');

  var hasStorage = !!(window.alfy && window.alfy.storage);

  function persist(){
    if(hasStorage){ try{ window.alfy.storage.set(KEY, entries); }catch(e){} }
  }
  function announce(msg){ statusEl.textContent = msg; }

  function fmtDate(ts){
    var d = new Date(ts);
    var s = new Date(); s.setHours(0,0,0,0);
    var t = new Date(ts); t.setHours(0,0,0,0);
    var diff = Math.round((s - t) / 86400000);
    var time = d.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    var label;
    if(diff === 0) label = 'Ma';
    else if(diff === 1) label = 'Tegnap';
    else if(diff > 1 && diff < 7) label = diff + ' napja';
    else label = d.toLocaleDateString('hu-HU', {year:'numeric', month:'long', day:'numeric'});
    return {label:label, time:time};
  }

  function icon(name){
    var p = {
      edit:'<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h4L18.5 9.5a2.1 2.1 0 0 0-3-3L5 17z"/><path d="M13.5 6.5l3 3"/></svg>',
      trash:'<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16"/><path d="M9 7V5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/><path d="M6 7l1 13a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1l1-13"/><path d="M10 11v6M14 11v6"/></svg>',
      check:'<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12l5 5 9-11"/></svg>',
      x:'<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M6 6l12 12M18 6L6 18"/></svg>'
    };
    return p[name] || '';
  }

  function render(){
    var filtered = query
      ? entries.filter(function(e){ return e.text.toLowerCase().indexOf(query) !== -1; })
      : entries;

    countEl.textContent = entries.length
      ? entries.length + ' bejegyzés' + (query ? ' · ' + filtered.length + ' találat' : '')
      : '';

    list.innerHTML = '';

    if(entries.length === 0){
      var empty = document.createElement('div');
      empty.className = 'empty';
      empty.innerHTML = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3h9l3 3v15H6z"/><path d="M9 9h6M9 13h6M9 17h4"/></svg>'
        + '<h3>Még nincs bejegyzés</h3>'
        + '<p>Írd le az első napodat fent, és mentsd el, hogy itt megjelenjen.</p>';
      var eb = document.createElement('button');
      eb.className = 'btn btn-primary';
      eb.type = 'button';
      eb.textContent = 'Írjam az elsőt';
      eb.addEventListener('click', function(){ input.focus(); });
      empty.appendChild(eb);
      list.appendChild(empty);
      return;
    }

    if(filtered.length === 0){
      var no = document.createElement('div');
      no.className = 'empty';
      no.innerHTML = '<h3>Nincs találat</h3><p>A(z) „' + query.replace(/</g,'&lt;') + '” keresésre nem találtunk bejegyzést.</p>';
      list.appendChild(no);
      return;
    }

    filtered.forEach(function(e){
      var card = document.createElement('article');
      card.className = 'entry';

      var top = document.createElement('div');
      top.className = 'entry-top';
      var date = fmtDate(e.ts);
      var dl = document.createElement('span');
      dl.className = 'entry-date';
      dl.textContent = date.label;
      var tm = document.createElement('span');
      tm.className = 'entry-time';
      tm.textContent = date.time;
      dl.appendChild(tm);

      var acts = document.createElement('div');
      acts.className = 'entry-actions';
      var editBtn = document.createElement('button');
      editBtn.className = 'icon-btn';
      editBtn.type = 'button';
      editBtn.title = 'Szerkesztés';
      editBtn.setAttribute('aria-label', 'Bejegyzés szerkesztése');
      editBtn.innerHTML = icon('edit');
      editBtn.addEventListener('click', function(){ editingId = e.id; confirmId = null; render(); focusEdit(); });
      var delBtn = document.createElement('button');
      delBtn.className = 'icon-btn';
      delBtn.type = 'button';
      delBtn.title = 'Törlés';
      delBtn.setAttribute('aria-label', 'Bejegyzés törlése');
      delBtn.innerHTML = icon('trash');
      delBtn.addEventListener('click', function(){ confirmId = e.id; render(); });
      acts.appendChild(editBtn);
      acts.appendChild(delBtn);

      top.appendChild(dl);
      top.appendChild(acts);
      card.appendChild(top);

      if(editingId === e.id){
        var wrap = document.createElement('div');
        wrap.className = 'entry-edit';
        var ta = document.createElement('textarea');
        ta.id = 'edit-' + e.id;
        ta.setAttribute('aria-label', 'Bejegyzés szövege');
        ta.value = e.text;
        ta.addEventListener('keydown', function(ev){
          if(ev.key === 'Enter' && (ev.ctrlKey || ev.metaKey)){ ev.preventDefault(); saveEdit(e.id, ta.value); }
        });
        var ef = document.createElement('div');
        ef.className = 'entry-edit-foot';
        var save = document.createElement('button');
        save.className = 'btn btn-primary'; save.type = 'button'; save.textContent = 'Mentés';
        save.addEventListener('click', function(){ saveEdit(e.id, ta.value); });
        var cancel = document.createElement('button');
        cancel.className = 'btn'; cancel.type = 'button'; cancel.textContent = 'Mégse';
        cancel.addEventListener('click', function(){ editingId = null; render(); });
        ef.appendChild(save); ef.appendChild(cancel);
        wrap.appendChild(ta); wrap.appendChild(ef);
        card.appendChild(wrap);
      } else {
        var body = document.createElement('p');
        body.className = 'entry-body';
        body.textContent = e.text;
        card.appendChild(body);
      }

      if(confirmId === e.id){
        var conf = document.createElement('div');
        conf.className = 'confirm';
        var cp = document.createElement('p');
        cp.textContent = 'Biztosan törlöd ezt a bejegyzést?';
        var cf = document.createElement('div');
        cf.className = 'confirm-actions';
        var yes = document.createElement('button');
        yes.className = 'btn btn-danger'; yes.type = 'button'; yes.textContent = 'Törlés';
        yes.addEventListener('click', function(){ removeEntry(e.id); });
        var no = document.createElement('button');
        no.className = 'btn'; no.type = 'button'; no.textContent = 'Mégse';
        no.addEventListener('click', function(){ confirmId = null; render(); });
        cf.appendChild(yes); cf.appendChild(no);
        conf.appendChild(cp); conf.appendChild(cf);
        card.appendChild(conf);
      }

      list.appendChild(card);
    });
  }

  function focusEdit(){
    var ta = document.getElementById('edit-' + editingId);
    if(ta){ ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
  }

  function addEntry(){
    var text = input.value.trim();
    if(!text){ announce('Írj valamit a mentéshez.'); input.focus(); return; }
    entries.unshift({ id: genId(), ts: Date.now(), text: text });
    input.value = '';
    input.style.height = 'auto';
    editingId = null; confirmId = null;
    persist(); render();
    announce('Bejegyzés hozzáadva.');
    input.focus();
  }

  function saveEdit(id, value){
    var text = value.trim();
    var e = entries.find(function(x){ return x.id === id; });
    if(!e) return;
    if(!text){ removeEntry(id); return; }
    e.text = text;
    editingId = null;
    persist(); render();
    announce('Bejegyzés frissítve.');
  }

  function removeEntry(id){
    entries = entries.filter(function(x){ return x.id !== id; });
    confirmId = null;
    if(editingId === id) editingId = null;
    persist(); render();
    announce('Bejegyzés törölve.');
  }

  function genId(){ return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

  addBtn.addEventListener('click', addEntry);
  input.addEventListener('keydown', function(ev){
    if(ev.key === 'Enter' && (ev.ctrlKey || ev.metaKey)){ ev.preventDefault(); addEntry(); }
  });
  search.addEventListener('input', function(){ query = search.value.trim().toLowerCase(); render(); });

  async function load(){
    if(hasStorage){
      try{
        var v = await window.alfy.storage.get(KEY);
        if(Array.isArray(v)) entries = v.filter(function(e){ return e && typeof e.text === 'string'; });
      }catch(e){}
    }
    render();
  }
  load();
})();
</script>
</body>
</html>
